#!/usr/bin/env python3
"""sites.json -> src/generated/sites.generated.h (run by build.ps1)."""

from __future__ import annotations

import sys
from pathlib import Path

from sitetable import Site, load

KIND_CPP = {
    "jmp": "Rs7Kind::Jmp",
    "jmp_atomic8": "Rs7Kind::JmpAtomic8",
    "rel32": "Rs7Kind::Rel32",
    "call": "Rs7Kind::Call",
    "ref": "Rs7Kind::Ref",
    "callref": "Rs7Kind::CallRef",
    "bytes": "Rs7Kind::Bytes",
}


def render(checksum: int, sites: list[Site]) -> str:
    lines = [
        "// Generated by tools/gen_sites.py from sites.json - do not edit.",
        "#pragma once",
        '#include "core/sites.h"',
        "",
        f"static const unsigned kRs7PeChecksum = 0x{checksum:08X}u;",
        "static const Rs7Site kRs7Sites[] = {",
    ]

    def row(s: Site) -> str:
        rel_at, rel_size, insn_end = s.target if s.target else (-1, 0, 0)
        expect = s.expect.hex(" ").upper()
        write = s.write.hex(" ").upper()
        return (
            f'    {{"{s.id}", "{s.pattern}", {s.offset}, "{expect}", {KIND_CPP[s.kind]}, '
            f'{s.length}, {rel_at}, {rel_size}, {insn_end}, "{write}"}},'
        )

    main = [s for s in sites if s.group != "psarc"]
    psarc = [s for s in sites if s.group == "psarc"]
    lines += [row(s) for s in main]
    lines += [
        "};",
        f"static const int kRs7SiteCount = {len(main)};",
        "",
        "// The plain-PSARC unit (core/plainpsarc.h): resolved and written early, on their own.",
        "static const Rs7Site kRs7PsarcSites[] = {",
    ]
    lines += [row(s) for s in psarc]
    lines += ["};", f"static const int kRs7PsarcSiteCount = {len(psarc)};", ""]
    return "\n".join(lines)


def main(argv: list[str]) -> int:
    src, dst = Path(argv[0]), Path(argv[1])
    checksum, sites = load(src)
    dst.parent.mkdir(parents=True, exist_ok=True)
    dst.write_text(render(checksum, sites), encoding="utf-8")
    print(f"{dst}: {len(sites)} sites")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
